// Suncoast City: the beachfront, the ocean, Ocean Ave and the downtown grid.
// Every mesh is built from primitives with procedurally painted canvas textures,
// so the whole city is original art generated by this file at load time.
import * as THREE from 'three';
import { mulberry32 } from './util.js';

const SUNSET = {
  sky: 0xff9a56, fog: 0xf78d4e, sun: 0xffd27a, sunPos: [-260, 55, -120],
  hemiSky: 0xffb37a, hemiGround: 0x3a2b4a, dir: 0xffc37a, dirIntensity: 1.5,
};
const DUSK = {
  sky: 0x35315e, fog: 0x2c2a52, sun: 0xff8f5e, sunPos: [-260, 26, -120],
  hemiSky: 0x6a6aa8, hemiGround: 0x1c1830, dir: 0xff9a6a, dirIntensity: 0.9,
};

/** Paint a building facade: dark wall, a grid of windows, some lit warm. */
function facadeTexture(rng, base, lit) {
  const c = document.createElement('canvas');
  c.width = 128;
  c.height = 256;
  const g = c.getContext('2d');
  g.fillStyle = base;
  g.fillRect(0, 0, 128, 256);
  for (let y = 10; y < 246; y += 22) {
    for (let x = 10; x < 118; x += 18) {
      g.fillStyle = rng() < lit ? '#ffd27a' : '#20242e';
      g.fillRect(x, y, 12, 14);
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

/** Paint a road surface with a centre line, for a plane of the given size. */
function roadTexture() {
  const c = document.createElement('canvas');
  c.width = 64;
  c.height = 256;
  const g = c.getContext('2d');
  g.fillStyle = '#23232b';
  g.fillRect(0, 0, 64, 256);
  g.fillStyle = '#e8c33c';
  g.fillRect(30, 0, 4, 256);
  g.fillStyle = '#d8d8d8';
  for (let y = 0; y < 256; y += 32) g.fillRect(6, y, 3, 18);
  for (let y = 0; y < 256; y += 32) g.fillRect(55, y, 3, 18);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function box(w, h, d, mat, x, y, z, ry = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.rotation.y = ry;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

/** Build the whole city into `scene`. Returns handles the loop animates. */
export function buildCity(scene, seed = 1) {
  const rng = mulberry32(seed);
  const group = new THREE.Group();
  scene.add(group);

  const sunLight = new THREE.DirectionalLight(SUNSET.dir, SUNSET.dirIntensity);
  sunLight.position.set(-120, 80, -60);
  sunLight.castShadow = true;
  sunLight.shadow.mapSize.set(2048, 2048);
  sunLight.shadow.camera.left = -180;
  sunLight.shadow.camera.right = 180;
  sunLight.shadow.camera.top = 180;
  sunLight.shadow.camera.bottom = -180;
  scene.add(sunLight);
  scene.add(new THREE.HemisphereLight(SUNSET.hemiSky, SUNSET.hemiGround, 0.9));
  scene.fog = new THREE.Fog(SUNSET.fog, 120, 520);

  // Ocean: a wide plane west of the beach, gently blue with a warm sunset tint.
  const oceanMat = new THREE.MeshStandardMaterial({ color: 0x1e6f8e, roughness: 0.25, metalness: 0.1 });
  const ocean = new THREE.Mesh(new THREE.PlaneGeometry(320, 520), oceanMat);
  ocean.rotation.x = -Math.PI / 2;
  ocean.position.set(-270, 0.15, 0);
  ocean.receiveShadow = true;
  group.add(ocean);

  // Beach sand and boardwalk.
  const sand = new THREE.Mesh(
    new THREE.PlaneGeometry(44, 520),
    new THREE.MeshStandardMaterial({ color: 0xe8c98f, roughness: 1 }),
  );
  sand.rotation.x = -Math.PI / 2;
  sand.position.set(-92, 0.1, 0);
  sand.receiveShadow = true;
  group.add(sand);
  const board = box(12, 0.4, 520, new THREE.MeshStandardMaterial({ color: 0x8a6a4a, roughness: 0.9 }), -64, 0.2, 0);
  group.add(board);

  // Ground base for the whole district.
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(340, 520),
    new THREE.MeshStandardMaterial({ color: 0x3d3a44, roughness: 1 }),
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.set(60, 0, 0);
  ground.receiveShadow = true;
  group.add(ground);

  // Ocean Ave (north-south) and the cross streets.
  const roadTex = roadTexture();
  const ave = new THREE.Mesh(new THREE.PlaneGeometry(20, 340), new THREE.MeshStandardMaterial({ map: roadTex, roughness: 0.9 }));
  ave.rotation.x = -Math.PI / 2;
  ave.position.set(-44, 0.25, 0);
  roadTex.repeat.set(1, 10);
  ave.receiveShadow = true;
  group.add(ave);
  for (const z of [-90, -30, 30, 90]) {
    const street = new THREE.Mesh(new THREE.PlaneGeometry(200, 12), new THREE.MeshStandardMaterial({ color: 0x23232b, roughness: 0.9 }));
    street.rotation.x = -Math.PI / 2;
    street.position.set(50, 0.25, z);
    street.receiveShadow = true;
    group.add(street);
  }

  // The pier: planks running out over the ocean at z = 30, cargo pickup at its end.
  const pierMat = new THREE.MeshStandardMaterial({ color: 0x7a5a3a, roughness: 0.9 });
  const pier = box(10, 0.6, 70, pierMat, -140, 0.8, 30);
  group.add(pier);
  for (let i = 0; i < 6; i++) {
    group.add(box(1, 3, 1, pierMat, -144.5, -0.5, 2 + i * 12));
    group.add(box(1, 3, 1, pierMat, -135.5, -0.5, 2 + i * 12));
  }

  // Ferris wheel on the beach at (-88, -55): rim, spokes, cabins, legs.
  const wheel = new THREE.Group();
  wheel.position.set(-88, 0, -55);
  const rimMat = new THREE.MeshStandardMaterial({ color: 0xff5e7a, emissive: 0x881133, roughness: 0.4 });
  const rim = new THREE.Mesh(new THREE.TorusGeometry(17, 0.7, 10, 40), rimMat);
  rim.position.y = 24;
  rim.castShadow = true;
  wheel.add(rim);
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(1.4, 1.4, 2, 12), new THREE.MeshStandardMaterial({ color: 0xffe9a8, emissive: 0x664411 }));
  hub.rotation.x = Math.PI / 2;
  hub.position.y = 24;
  wheel.add(hub);
  const cabins = [];
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    const cabin = box(3.4, 2.6, 2.6, new THREE.MeshStandardMaterial({ color: [0xffe066, 0x6ad7ff, 0xff8fb0][i % 3], roughness: 0.5 }), Math.cos(a) * 17, 24 + Math.sin(a) * 17, 0);
    wheel.add(cabin);
    cabins.push(cabin);
    const spoke = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 17, 6), rimMat);
    spoke.position.set(Math.cos(a) * 8.5, 24 + Math.sin(a) * 8.5, 0);
    spoke.rotation.z = a + Math.PI / 2;
    wheel.add(spoke);
  }
  wheel.add(box(1.4, 26, 1.4, new THREE.MeshStandardMaterial({ color: 0xdddddd }), -6, 12, 0, 0.25));
  wheel.add(box(1.4, 26, 1.4, new THREE.MeshStandardMaterial({ color: 0xdddddd }), 6, 12, 0, -0.25));
  group.add(wheel);

  // The sun: a big glowing disc low over the ocean.
  const sunDisc = new THREE.Mesh(
    new THREE.CircleGeometry(26, 40),
    new THREE.MeshBasicMaterial({ color: SUNSET.sun, fog: false }),
  );
  sunDisc.position.set(-290, 48, -140);
  sunDisc.lookAt(0, 20, 0);
  scene.add(sunDisc);

  // Downtown blocks: seeded towers with lit windows, east of Ocean Ave.
  const palettes = ['#5a4a6a', '#4a5a6a', '#6a4a4a', '#44505e', '#5e5a44'];
  const buildings = [];
  for (let bx = -16; bx <= 140; bx += 34) {
    for (let bz = -150; bz <= 150; bz += 52) {
      if (Math.abs(bz + 90) < 12 || Math.abs(bz + 30) < 12 || Math.abs(bz - 30) < 12 || Math.abs(bz - 90) < 12) continue;
      if (bx < 0 && bz > -20 && bz < 60) continue; // keep the yard near (20, 30) open for job 4
      if (bx >= 0 && bx < 48 && bz >= -10 && bz < 48) continue; // same yard, east side: no tower on it
      const w = 18 + rng() * 10;
      const d = 18 + rng() * 10;
      const h = 16 + rng() * rng() * 70;
      const tex = facadeTexture(rng, palettes[Math.floor(rng() * palettes.length)], 0.35 + rng() * 0.3);
      const b = box(w, h, d, new THREE.MeshStandardMaterial({ map: tex, roughness: 0.85 }), bx + w / 2, h / 2, bz + d / 2);
      group.add(b);
      buildings.push(b);
      // Rooftop box, for the skyline.
      group.add(box(w * 0.3, 3, d * 0.3, new THREE.MeshStandardMaterial({ color: 0x2a2a33 }), bx + w / 2, h + 1.5, bz + d / 2));
    }
  }

  // Palms along the beach edge and Ocean Ave.
  const palms = [];
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x7a5a3a, roughness: 1 });
  const frondMat = new THREE.MeshStandardMaterial({ color: 0x2f9e5f, roughness: 0.8 });
  function palm(x, z) {
    const p = new THREE.Group();
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.55, 9, 8), trunkMat);
    trunk.position.y = 4.5;
    trunk.rotation.z = 0.08;
    trunk.castShadow = true;
    p.add(trunk);
    for (let i = 0; i < 6; i++) {
      const frond = new THREE.Mesh(new THREE.ConeGeometry(1.1, 5.5, 6), frondMat);
      const a = (i / 6) * Math.PI * 2;
      frond.position.set(Math.cos(a) * 1.8, 9.4, Math.sin(a) * 1.8);
      frond.rotation.z = Math.cos(a) * 1.1;
      frond.rotation.x = -Math.sin(a) * 1.1;
      frond.castShadow = true;
      p.add(frond);
    }
    p.position.set(x, 0, z);
    group.add(p);
    palms.push(p);
    return p;
  }
  for (let z = -160; z <= 160; z += 22) palm(-70 + (rng() - 0.5) * 3, z);
  for (let z = -150; z <= 150; z += 40) palm(-32, z);

  // Streetlights along Ocean Ave.
  const lampMat = new THREE.MeshStandardMaterial({ color: 0x333338, roughness: 0.6 });
  const lampGlow = new THREE.MeshStandardMaterial({ color: 0xffe9a8, emissive: 0xffc866, emissiveIntensity: 1.4 });
  for (let z = -160; z <= 160; z += 32) {
    group.add(box(0.35, 8, 0.35, lampMat, -34, 4, z));
    const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.7, 10, 8), lampGlow);
    bulb.position.set(-34, 8.2, z);
    group.add(bulb);
  }

  // A few beach umbrellas for colour.
  for (let i = 0; i < 6; i++) {
    const x = -100 + rng() * 16;
    const z = -140 + rng() * 280;
    const umb = new THREE.Mesh(
      new THREE.ConeGeometry(4, 2.2, 10),
      new THREE.MeshStandardMaterial({ color: [0xff6b6b, 0x6ad7ff, 0xffe066][i % 3], roughness: 0.7 }),
    );
    umb.position.set(x, 4.6, z);
    umb.castShadow = true;
    group.add(umb);
    group.add(box(0.18, 4.6, 0.18, trunkMat, x, 2.3, z));
  }

  return { group, wheel, cabins, ocean, oceanMat, sunDisc, sunLight, buildings, palms };
}

/** Switch the light rig between sunset and dusk. */
export function applyTimeOfDay(city, mode, scene) {
  const t = mode === 'dusk' ? DUSK : SUNSET;
  scene.background = new THREE.Color(t.sky);
  scene.fog.color.setHex(t.fog);
  city.sunLight.color.setHex(t.dir);
  city.sunLight.intensity = t.dirIntensity;
  city.sunDisc.material.color.setHex(t.sun);
  city.sunDisc.position.y = mode === 'dusk' ? 26 : 48;
  city.sunLight.position.set(-120, mode === 'dusk' ? 40 : 80, -60);
}

/** Animate the wheel and the ocean swell. */
export function updateCity(city, dt, time) {
  city.wheel.rotation.z += dt * 0.12;
  for (let i = 0; i < city.cabins.length; i++) {
    city.cabins[i].rotation.z = -city.wheel.rotation.z;
  }
  city.ocean.position.y = 0.15 + Math.sin(time * 0.6) * 0.08;
}
